<?php $__env->startSection('title',$page->exists ? 'Edit Page' : 'Add Page'); ?>
<?php $__env->startSection('content'); ?>
<div class="content-heading mb-4"><h1><?php echo e($page->exists ? 'Edit Page' : 'Add New Page'); ?></h1><p>Content becomes available at its public page URL when published.</p></div>
